using System;using System.IO;using System.Linq;using System.Text.RegularExpressions;using System.Collections.Generic;
namespace Ara {public static class NotionDiary {
 public const string Begin="ARA-DAY-DATA-BEGIN-V1",End="ARA-DAY-DATA-END-V1";
 public static bool Active(Dictionary<string,object> input){var d=JsonMap.Child(input,"diary");if(d.Count==0)throw new InvalidDataException("하루 기록 본문 데이터가 없습니다.");string date=NotionDaily.Date(input);if(date!=JsonMap.Str(d,"wake_date")||!JsonMap.Str(d,"wake_at").StartsWith(date+"T"))throw new InvalidDataException("일기 날짜와 기상일이 다릅니다.");if(!d.ContainsKey("actual"))throw new InvalidDataException("행동 기록 형식을 확인해 주세요.");bool active=false;foreach(var row in JsonMap.Items(d,"actual")){var r=JsonMap.Map(row);int count; if(!int.TryParse(JsonMap.Str(r,"slot_count"),out count)||count<1||count>288)throw new InvalidDataException("행동 기록 길이를 확인해 주세요.");if(JsonMap.Str(r,"category_id")!="기상"&&JsonMap.Str(r,"template_id")!="wake")active=true;}return active;}
 public static Dictionary<string,object> Save(Dictionary<string,object> input,Dictionary<string,object> target,bool pending,NotionDaily.Call call,Action<bool> mark){if(!Active(input))return JsonMap.Obj("skipped",true,"reason","no_activity","date",JsonMap.Str(input,"date"));return NotionDaily.Save(input,target,pending,call,mark);}
 public static string Content(Dictionary<string,object> input){if(!input.ContainsKey("diary"))return null;Active(input);return Begin+"\n```json\n"+JsonMap.Write(input["diary"])+"\n```\n"+End;}
 public static Dictionary<string,object> NewPage(Dictionary<string,object> props,Dictionary<string,object> input){return JsonMap.Obj("properties",props); }
 public static string Body(Dictionary<string,object> fetched){if(!fetched.ContainsKey("text"))throw new InvalidDataException("노션 본문을 확인하지 못했습니다.");string text=JsonMap.Str(fetched,"text");int a=text.IndexOf("<content>"),b=text.LastIndexOf("</content>");return a>=0&&b>a?text.Substring(a+9,b-a-9):text;}
 public static Dictionary<string,object> Patch(string pageId,string body,string replacement){var a=Regex.Matches(body,"(?m)^"+Begin+"[ \\t]*$");var b=Regex.Matches(body,"(?m)^"+End+"[ \\t]*$");var request=JsonMap.Obj("page_id",pageId,"allow_async",false);if(a.Count==0&&b.Count==0){if(body.Contains(Begin)||body.Contains(End))throw new InvalidDataException("ARA 기록 구역 표시를 확인해 주세요. 본문은 보존했습니다.");request["command"]="insert_content";request["position"]=JsonMap.Obj("type","end");request["content"]=replacement;return request;}if(a.Count!=1||b.Count!=1||b[0].Index<a[0].Index)throw new InvalidDataException("ARA 기록 구역의 시작·끝 표시가 변경됐습니다. 다른 본문은 수정하지 않았습니다.");string old=body.Substring(a[0].Index,b[0].Index+b[0].Length-a[0].Index);if(old==replacement)return null;request["command"]="update_content";request["content_updates"]=new[]{JsonMap.Obj("old_str",old,"new_str",replacement)};return request;}
 public const string ChildPending="ARA-AI-CHILD-PENDING-V1";
 public static void WritePatch(Dictionary<string,object> request,NotionDaily.Call call){if(request==null)return;var result=NotionDaily.Decode(call("update-page",request));if(JsonMap.Str(result,"type")=="async_task"||result.ContainsKey("async_task"))throw new InvalidOperationException("노션 본문 처리 중입니다. 다음 동기화에서 다시 확인합니다.");}
 public static string ChildId(string body,string title){var found=Regex.Matches(body,@"<page\b[^>]*url=""([^""]+)""[^>]*>([^<]*)</page>").Cast<Match>().Where(m=>m.Groups[2].Value.Trim()==title).ToArray();if(found.Length>1)throw new InvalidDataException("AI 참고 기록 하위 페이지가 여러 개 있습니다.");return found.Length==0?"":NotionDaily.Id(found[0].Groups[1].Value.Trim('{','}'));}
 public static void Update(string pageId,Dictionary<string,object> input,NotionDaily.Call call){string content=Content(input);if(content==null)return;string parentBody=Body(NotionDaily.Decode(call("fetch",JsonMap.Obj("id",pageId)))),title="ARA AI 기록 · "+NotionDaily.Date(input),childId=ChildId(parentBody,title);if(childId.Length==0){if(parentBody.Contains(ChildPending))throw new InvalidOperationException("AI 하위 페이지 생성 결과를 확인 중입니다. 다음 동기화에서 다시 확인합니다.");WritePatch(JsonMap.Obj("page_id",pageId,"command","insert_content","position",JsonMap.Obj("type","end"),"content",ChildPending,"allow_async",false),call);var created=NotionDaily.Decode(call("create-pages",JsonMap.Obj("parent",JsonMap.Obj("page_id",pageId),"allow_async",false,"pages",new[]{JsonMap.Obj("properties",JsonMap.Obj("title",title),"content",content)})));var pages=JsonMap.Items(created,"pages");if(pages.Length==0)pages=JsonMap.Items(created,"results");var child=pages.Length>0?JsonMap.Map(pages[0]):created;childId=NotionDaily.Id(JsonMap.Str(child,"url").Length>0?JsonMap.Str(child,"url"):JsonMap.Str(child,"id"));}else{string childBody=Body(NotionDaily.Decode(call("fetch",JsonMap.Obj("id",childId))));if(!childBody.Contains(Begin)||!childBody.Contains(End))throw new InvalidDataException("AI 하위 페이지의 ARA 기록 구역을 확인해 주세요.");WritePatch(Patch(childId,childBody,content),call);}parentBody=Body(NotionDaily.Decode(call("fetch",JsonMap.Obj("id",pageId))));if(parentBody.Contains(Begin)||parentBody.Contains(End))WritePatch(Patch(pageId,parentBody,""),call);if(parentBody.Contains(ChildPending))WritePatch(JsonMap.Obj("page_id",pageId,"command","update_content","content_updates",new[]{JsonMap.Obj("old_str",ChildPending,"new_str","")},"allow_async",false),call);}

 public static Dictionary<string,object> Payload(State state,string date){var raw=DailyExport.Create(state,date);var data=JsonMap.Read(JsonMap.Write(raw));var s=Store.Clone(state);var day=s.GetDay(PhoneCodec.Date(date));var p=GridEngine.Build(s,day);var stats=SatisfactionPolicy.Calculate(s,day,Adaptive.EstimatedSleep(s,day,p),DateTime.Now);var actual=day.Records.Where(x=>x.Start>=day.Wake).ToArray();int slots=actual.Sum(x=>x.Count);decimal total=actual.Sum(x=>x.Score*x.Count),sat=GridEngine.SatisfactionAverage(s,day,p);data["schema_version"]="4";data["storage_layout"]="ai_child_page_v1";data["day_id"]=raw.wake_date;data["source_date"]=date;data["source"]="ARA Daily OS";var ah=Adherence.Report(day);ah["time_origin"]=date+"T00:00:00+09:00";ah["time_unit"]="minutes_from_origin";data["adherence"]=ah;data["summary"]=JsonMap.Obj("adherence_score",ah["score"],"adherence_evaluated_actions",ah["evaluated_actions"],"focus_total",total,"focus_average_recorded",slots>0?Math.Round(total/slots,2,MidpointRounding.AwayFromZero):0,"satisfaction_time_weighted",Math.Round(sat,2,MidpointRounding.AwayFromZero),"recorded_minutes",slots*10);data["tasks"]=JsonMap.Items(data,"tasks").Where(t=>JsonMap.Str(JsonMap.Map(t),"done")=="True").ToArray();data["actual"]=JsonMap.Items(data,"actual").Where(row=>DateTime.Parse(JsonMap.Str(JsonMap.Map(row),"start_at"))>=day.Wake).ToArray();data["satisfaction_policy"]=JsonMap.Obj("blank_score",s.ExcludeBlankSatisfaction?null:(object)s.BlankSatisfaction,"include_blank",!s.ExcludeBlankSatisfaction,"minutes_in_average",stats.Minutes,"slot_minutes",10,"range","wake_to_now_capped_at_sleep","from",raw.wake_at,"to",DailyExport.Stamp(stats.Finish),"slots",Math.Max(0,(int)Math.Ceiling((stats.Finish-day.Wake).TotalMinutes/10)));return JsonMap.Obj("op","diary","date",raw.wake_date,"minutes",slots*10,"focusTotal",total,"focusAverage",slots>0?Math.Round(total/slots,2,MidpointRounding.AwayFromZero):0,"satisfactionAverage",Math.Round(sat,2,MidpointRounding.AwayFromZero),"diary",data);}
